import csv
import json
import zipfile
from collections import defaultdict

# Read stops file
stops_data = defaultdict(list)
with zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip', 'r') as zf:
    zf.read('stops.txt').decode('utf-8')

with open('stops.txt', 'r') as f:
    lines = f.readlines()

header = None
for line in lines:
    line = line.strip()
    if not line:
        continue
    parts = line.split(',')
    stop_id = parts[0]
    stop_name = parts[1]
    stop_lat = parts[2]
    stop_lon = parts[3]

    if header:
        # Validate stop: must have 4 fields
        if len(parts) == 4:
            try:
                float(stop_lat)
                float(stop_lon)
                # Check for duplicates
                if stop_id not in stops_data:
                    stops_data[stop_id] = []
            except ValueError:
                # Invalid coordinates, skip
                continue
    else:
        header = parts
        if stop_id == '':
            continue
        stops_data[stop_id] = []

# Read trips file
trip_data = defaultdict(list)
with zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip', 'r') as zf:
    zf.read('trips.txt').decode('utf-8')

with open('trips.txt', 'r') as f:
    lines = f.readlines()

header = None
for line in lines:
    line = line.strip()
    if not line:
        continue
    parts = line.split(',')
    route_id = parts[0]
    service_id = parts[1]
    trip_id = parts[2]
    shape_id = parts[3]

    if header:
        if len(parts) == 4:
            try:
                float(shape_id)
                # Check for duplicates
                if shape_id not in trip_data:
                    trip_data[shape_id] = []
            except ValueError:
                continue
    else:
        header = parts
        if route_id == '' or service_id == '':
            continue
        trip_data[route_id] = []

# Read stop_times file
stop_times_data = defaultdict(list)
with zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip', 'r') as zf:
    zf.read('stop_times.txt').decode('utf-8')

with open('stop_times.txt', 'r') as f:
    lines = f.readlines()

header = None
for line in lines:
    line = line.strip()
    if not line:
        continue
    parts = line.split(',')
    trip_id = parts[0]
    arrival_time = parts[1]
    departure_time = parts[2]
    stop_id = parts[3]
    stop_sequence = parts[4]

    if header:
        if len(parts) == 5:
            try:
                float(arrival_time)
                float(departure_time)
                # Check for duplicates
                if stop_id not in stop_times_data:
                    stop_times_data[stop_id] = []
            except ValueError:
                continue
    else:
        header = parts
        if trip_id == '' or stop_id == '':
            continue
        stop_times_data[stop_id] = []

# Validate stop names
stop_name_map = {}
valid_stop_ids = set()
for stop_id, stops in stops_data.items():
    valid_stop_ids.add(stop_id)
    for stop in stops:
        if stop_name_map.get(stop) is None:
            # Check if stop name exists in valid stops
            found = False
            for other_id, other_stops in stops_data.items():
                if stop in other_stops:
                    stop_name_map[stop] = other_id
                    found = True
                    break
            if not found:
                # Stop name is invalid, fill with empty string
