        if len(parts) == 5:
            try:
                float(arrival_time)
                float(departure_time)
                # Check for duplicates
                if stop_id not in stop_times_data:
                    stop_times_data[stop_id] = []
            except ValueError:
                continue
    else:
        header = parts
        if trip_id == '' or stop_id == '':
            continue
        stop_times_data[stop_id] = []

# Validate stop names
stop_name_map = {}
valid_stop_ids = set()
for stop_id, stops in stops_data.items():
    valid_stop_ids.add(stop_id)
    for stop in stops:
        if stop_name_map.get(stop) is None:
            # Check if stop name exists in valid stops
            found = False
            for other_id, other_stops in stops_data.items():
                if stop in other_stops:
                    stop_name_map[stop] = other_id
                    found = True
                    break
            if not found:
                # Stop name is invalid, fill with empty string
                stop_name_map[stop] = ''
        else:
            # Stop name already valid
            pass

# Read valid stops
valid_stop_ids = set()
for stop_id, stops in stops_data.items():
    valid_stop_ids.add(stop_id)

# Read valid trips
valid_trip_ids = set()
for route_id, trips in trip_data.items():
    valid_trip_ids.add(route_id)

# Read valid stop times
valid_stop_times = set()
for stop_id, times in stop_times_data.items():
    valid_stop_times.add(stop_id)

# Create mapping from valid stop_id to valid trip_id
stop_to_trip = {}
for stop_id, stops in stops_data.items():
    if stop_id in valid_stop_ids:
        for trip_id, trips in trip_data.items():
            for trip in trips:
                if trip['stop_id'] == stop_id:
                    stop_to_trip[stop_id] = trip_id
                    break

# Read valid stop times with stop_id
valid_stop_times_with_sequence = defaultdict(list)
for stop_id, times in stop_times_data.items():
    if stop_id in valid_stop_times:
        for trip_id, times in times:
            valid_stop_times_with_sequence[stop_id].append({
                'trip_id': trip_id,
                'arrival_time': times[0],
                'departure_time': times[1],
                'stop_id': stop_id,
                'stop_sequence': int(times[4])
            })

# Identify invalid stop times
invalid_stop_times = []
for stop_id, times in valid_stop_times_with_sequence.items():
    for i, trip in enumerate(times):
        if trip['stop_id'] not in valid_stop_ids:
            invalid_stop_times.append({
                'trip_id': trip['trip_id'],
                'arrival_time': trip['arrival_time'],
                'departure_time': trip['departure_time'],
                'stop_id': trip['stop_id'],
                'stop_sequence': trip['stop_sequence']
            })

# Count invalid stop times
invalid_stop_count = len(invalid_stop_times)

# Read valid stops and create cleaned stops
cleaned_stops = []
for stop_id, stops in stops_data.items():
    if stop_id in valid_stop_ids:
        for stop in stops:
            cleaned_stops.append({
                'stop_id': stop_id,
                'stop_name': stop_name_map.get(stop, ''),
                'stop_lat': float(stop_lat),
                'stop_lon': float(stop_lon)
            })

# Sort by stop_id
cleaned_stops.sort(key=lambda x: x['stop_id'])

# Count valid and invalid stop times
valid_stop_times_count = 0
for stop_id, times in valid_stop_times_with_sequence.items():
    if stop_id in valid_stop_times:
        valid_stop_times_count += len(times)

# Count invalid stop times
invalid_stop_times_count = len(invalid_stop_times)

# Create report
report = {
    'invalid_coordinates_removed': 0,
    'duplicate_stops_removed': 0,
    'missing_stop_names_filled': 0,
    'n_clean_stops': len(cleaned_stops),
    'n_clean_stop_times': invalid_stop_times_count
}

# Write cleaned stops CSV
with open('outputs/t05_clean_stops.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['stop_id', 'stop_name', 'stop_lat', 'stop_lon'])
    for stop in cleaned_stops:
        writer.writerow([stop['stop_id'], stop['stop_name'], stop['stop_lat'], stop['stop_lon']])

# Write cleaned stop times CSV
with open('outputs/t05_clean_stop_times.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['trip_id', 'arrival_time', 'departure_time', 'stop_id', 'stop_sequence'])
    for trip in invalid_stop_times:
        writer.writerow([trip['trip_id'], trip['arrival_time'], trip['departure_time'], trip['stop_id'], trip['stop_sequence']])

# Write report
with open('outputs/t05_gtfs_cleaning_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print(f"Report: {report}")
print(f"Cleaned stops: {len(cleaned_stops)}")
print(f"Cleaned stop times: {invalid_stop_times_count}")
print(f"Invalid stop times: {invalid_stop_count}")
